import { basename } from 'node:path';
import { OPTION_NAME, OPTION_VALUE_NAME } from './constants.mjs';

function getProgramName(scriptPath) {
  return basename(scriptPath || 'test2.mjs');
}

function getUsageLine(scriptPath) {
  return `usage: ${getProgramName(scriptPath)} [-h] ${OPTION_NAME} ${OPTION_VALUE_NAME}`;
}

export function buildHelpText(scriptPath) {
  return `${getUsageLine(scriptPath)}\n\noptions:\n  -h, --help  show this help message and exit\n  ${OPTION_NAME} ${OPTION_VALUE_NAME}\n`;
}

export function buildRequiredArgumentError(scriptPath) {
  return `${getUsageLine(scriptPath)}\n${getProgramName(scriptPath)}: error: the following arguments are required: ${OPTION_NAME}\n`;
}

export function buildExpectedArgumentError(scriptPath) {
  return `${getUsageLine(scriptPath)}\n${getProgramName(scriptPath)}: error: argument ${OPTION_NAME}: expected one argument\n`;
}

export function buildUnrecognizedArgumentsError(scriptPath, extras) {
  return `${getUsageLine(scriptPath)}\n${getProgramName(scriptPath)}: error: unrecognized arguments: ${extras.join(' ')}\n`;
}

